var TIMEOUT_MS = 125e3;
var AI_BASE = (import.meta.env?.VITE_AI_BASE_URL ?? "/api").replace(/\/+$/, "");
var SYSTEM_PROMPT = "\u4F60\u662F\u5730\u56FE\u5B66\u8BFE\u7A0B\u7684\u52A9\u6559\uFF0C\u9762\u5411\u672C\u79D1\u751F\u56DE\u7B54\u5730\u56FE\u5B66\u95EE\u9898\uFF0C\u8303\u56F4\u5305\u62EC\u5730\u56FE\u6295\u5F71\u3001\u5750\u6807\u7CFB\u4E0E\u5927\u5730\u57FA\u51C6\u3001\u6BD4\u4F8B\u5C3A\u3001\u5730\u56FE\u7B26\u53F7\u3001\u5236\u56FE\u7EFC\u5408\u3001GIS \u57FA\u7840\u3002\u56DE\u7B54\u8981\u51C6\u786E\u3001\u7B80\u6D01\u3001\u6709\u6761\u7406\uFF0C\u5FC5\u8981\u65F6\u4E3E\u4F8B\uFF1B\u4E0D\u786E\u5B9A\u65F6\u5982\u5B9E\u8BF4\u660E\uFF0C\u4E0D\u8981\u7F16\u9020\u3002";
async function askByAI(history) {
  const messages = [
    { role: "system", content: SYSTEM_PROMPT },
    // 只携带最近 10 条上下文，控制 token 与超时风险（spec/07 §3.2）
    ...history.slice(-10)
  ];
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const resp = await fetch(`${AI_BASE}/ai/recommend`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ messages }),
      signal: controller.signal
    });
    if (!resp.ok) throw new Error(`AI \u4EE3\u7406\u8FD4\u56DE ${resp.status}`);
    const data = await resp.json();
    const text = data.content?.trim() ?? "";
    if (!text) throw new Error("AI \u54CD\u5E94\u4E3A\u7A7A");
    return text;
  } finally {
    clearTimeout(timer);
  }
}
